import{_ as a,o as t,c as i,ag as r}from"./chunks/framework.BZohXCq9.js";const u=JSON.parse('{"title":"Teacher Dashboard -> Profile Price Management (deep)","description":"","frontmatter":{},"headers":[],"relativePath":"modules/teacher-dashboard/profile-price-management.md","filePath":"modules/teacher-dashboard/profile-price-management.md"}'),l={name:"modules/teacher-dashboard/profile-price-management.md"};function o(d,e,c,s,n,h){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="teacher-dashboard-profile-price-management-deep" tabindex="-1">Teacher Dashboard -&gt; Profile Price Management (deep) <a class="header-anchor" href="#teacher-dashboard-profile-price-management-deep" aria-label="Permalink to &quot;Teacher Dashboard -&gt; Profile Price Management (deep)&quot;">​</a></h1><p><strong>Module:</strong> <code>teacher-dashboard</code><br><strong>Feature:</strong> <code>profile-price-management</code><br><strong>Surface:</strong> Price Management tab inside <code>/teacher-dashboard/settings</code></p><p>This tab lets the instructor manage lesson pricing, lesson discount, and bulk lesson packages.</p><h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><ul><li>Set base lesson fee.</li><li>Apply lesson-level discount.</li><li>Calculate final lesson price.</li><li>Build bulk lesson packages with package-specific discount and end date.</li></ul><h2 id="frontend-files" tabindex="-1">Frontend files <a class="header-anchor" href="#frontend-files" aria-label="Permalink to &quot;Frontend files&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Role</th><th>Integration</th></tr></thead><tbody><tr><td><code>Frontend/src/pages/private/teacher-dashboard/tabs/TariffTab.tsx</code></td><td>Main tariff/price UI</td><td>Calls <code>GET_TEACHER_TARIFF</code> and <code>UPDATE_TEACHER_TARIFF</code>; calculates price values client-side before saving.</td></tr><tr><td><code>Frontend/src/graphql/mutations/tariff.ts</code></td><td>Tariff GraphQL</td><td>Defines teacher tariff query and mutation.</td></tr></tbody></table><h2 id="frontend-graphql" tabindex="-1">Frontend GraphQL <a class="header-anchor" href="#frontend-graphql" aria-label="Permalink to &quot;Frontend GraphQL&quot;">​</a></h2><h3 id="get-teacher-tariff" tabindex="-1"><code>GET_TEACHER_TARIFF</code> <a class="header-anchor" href="#get-teacher-tariff" aria-label="Permalink to &quot;`GET_TEACHER_TARIFF`&quot;">​</a></h3><ul><li>File: <code>Frontend/src/graphql/mutations/tariff.ts</code></li><li>Query field: <code>teacherTariff</code></li><li>Used by: <code>TariffTab.tsx</code></li><li>Provides: <ul><li><code>lessonFee</code></li><li><code>lessonDiscount</code></li><li><code>FinalPricePerLesson</code></li><li><code>bulkPackages</code></li><li><code>isDefault</code></li></ul></li></ul><h3 id="update-teacher-tariff" tabindex="-1"><code>UPDATE_TEACHER_TARIFF</code> <a class="header-anchor" href="#update-teacher-tariff" aria-label="Permalink to &quot;`UPDATE_TEACHER_TARIFF`&quot;">​</a></h3><ul><li>File: <code>Frontend/src/graphql/mutations/tariff.ts</code></li><li>Mutation field: <code>updateTeacherTariff(input: TeacherTariffInput!)</code></li><li>Used by: <code>TariffTab.tsx</code></li><li>Refetches <code>GET_TEACHER_TARIFF</code> after save</li></ul><h2 id="backend-schema" tabindex="-1">Backend schema <a class="header-anchor" href="#backend-schema" aria-label="Permalink to &quot;Backend schema&quot;">​</a></h2><h3 id="typedefs" tabindex="-1">TypeDefs <a class="header-anchor" href="#typedefs" aria-label="Permalink to &quot;TypeDefs&quot;">​</a></h3><ul><li>File: <code>server/src/schemas/tariff.schema.js</code></li><li>Relevant query: <ul><li><code>teacherTariff: TeacherTariff</code></li></ul></li><li>Relevant mutation: <ul><li><code>updateTeacherTariff(input: TeacherTariffInput!): TeacherTariff</code></li></ul></li><li>Relevant types: <ul><li><code>TeacherTariff</code></li><li><code>TeacherTariffInput</code></li><li><code>BulkLessonPackage</code></li><li><code>BulkLessonPackageInput</code></li></ul></li></ul><h3 id="resolvers" tabindex="-1">Resolvers <a class="header-anchor" href="#resolvers" aria-label="Permalink to &quot;Resolvers&quot;">​</a></h3><ul><li>File: <code>server/src/graphql/resolvers/tariff.resolver.js</code></li><li>Relevant resolvers: <ul><li><code>Query.teacherTariff</code></li><li><code>Mutation.updateTeacherTariff</code></li></ul></li></ul><h2 id="main-backend-dependencies" tabindex="-1">Main backend dependencies <a class="header-anchor" href="#main-backend-dependencies" aria-label="Permalink to &quot;Main backend dependencies&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Role</th></tr></thead><tbody><tr><td><code>server/src/models/teacherTariff.model.js</code></td><td>Stores lesson fee, lesson discount, final price, and bulk packages</td></tr></tbody></table><h2 id="data-flow" tabindex="-1">Data flow <a class="header-anchor" href="#data-flow" aria-label="Permalink to &quot;Data flow&quot;">​</a></h2><ol><li>Instructor opens the Price Management tab.</li><li><code>GET_TEACHER_TARIFF</code> loads existing tariff data.</li><li><code>TariffTab.tsx</code> initializes local state from the response.</li><li>The tab recalculates derived values like final lesson price, package total, student savings, and final package price in the frontend.</li><li>Save action sends the full tariff payload through <code>UPDATE_TEACHER_TARIFF</code>.</li><li>Backend stores the updated tariff record and the UI refetches the latest saved values.</li></ol><h2 id="developer-notes" tabindex="-1">Developer notes <a class="header-anchor" href="#developer-notes" aria-label="Permalink to &quot;Developer notes&quot;">​</a></h2><ul><li>The tab performs significant client-side calculation, but the canonical stored values still live in <code>teacherTariff</code>.</li><li>There is a known ecosystem mismatch around some package/discount fields in other public-facing schema files; the teacher tariff model is the authoritative source for this tab’s saved data.</li></ul>',23)])])}const p=a(l,[["render",o]]);export{u as __pageData,p as default};
